package local.pitv;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.Typeface;import android.text.TextUtils;import android.view.*;import android.widget.*;import org.json.*;import org.xmlpull.v1.*;import java.io.*;import java.net.*;import java.util.*;import java.util.concurrent.*;

/** Small foreground-only weather/news feeds with timestamped last-success caching. */
final class HomeInfoTicker extends ResumeMarquee {
 final boolean weather;final Handler handler=new Handler();final ExecutorService worker=Executors.newSingleThreadExecutor();final android.content.SharedPreferences prefs;boolean active,closed;int generation;final Runnable refresh=()->fetch();
 HomeInfoTicker(Context context,boolean weather){super(context,weather?"weatherScroll":"newsScroll");this.weather=weather;prefs=context.getSharedPreferences("home-info",0);setTextSize(12);setTypeface(Typeface.MONOSPACE,weather?Typeface.BOLD:Typeface.NORMAL);setTextColor(weather?TvStyle.AMBER:TvStyle.SILVER);setSingleLine(true);setEllipsize(null);setHorizontallyScrolling(true);setSelected(true);setGravity(Gravity.CENTER_VERTICAL);setPadding(TvStyle.dp(context,10),0,TvStyle.dp(context,10),0);setBackgroundColor(0xff182332);setText(weather?"Loading weather…":"Loading headlines…");if(weather){setFocusable(true);setClickable(true);setContentDescription("Local weather. Press OK to change city or ZIP code.");setOnClickListener(v->location());setOnFocusChangeListener((v,focus)->setBackground(TvStyle.shape(context,0xff182332,focus?TvStyle.CYAN:0xff182332)));}showCache(false);}
 String key(){return weather?"weatherV2":"newsV2";}
 long interval(){return weather?20*60*1000:15*60*1000;}
 void resume(){if(closed||active)return;active=true;setScrolling(true);showCache(false);long age=System.currentTimeMillis()-prefs.getLong(key()+"At",0);if(age>=0&&age<interval())handler.postDelayed(refresh,interval()-age);else fetch();}
 void pause(){setScrolling(false);active=false;generation++;handler.removeCallbacks(refresh);}void close(){pause();closed=true;worker.shutdownNow();}
 String stamp(long time){return new java.text.SimpleDateFormat("MMM d, h:mm a z",Locale.US).format(new Date(time));}
 void showCache(boolean failed){String value=prefs.getString(key()+"Text","");long at=prefs.getLong(key()+"At",0);if(!value.isEmpty()){boolean stale=failed||System.currentTimeMillis()-at>interval();String tape=value+(stale?"     •     OFFLINE · Saved conditions/headlines":"")+"     ";setText(weather?tape:newsStyle(tape));}else if(failed)setText((weather?"Weather":"Headlines")+" temporarily unavailable · will retry     ");}
 static CharSequence newsStyle(String tape){android.text.SpannableString text=new android.text.SpannableString(tape);int start=0;for(String part:tape.split("     •     ",-1)){if(part.trim().matches("(?i)^(breaking(?: news)?|urgent|news alert)\\b.*")){text.setSpan(new android.text.style.ForegroundColorSpan(0xffff6b72),start,start+part.length(),android.text.Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);text.setSpan(new android.text.style.StyleSpan(Typeface.BOLD),start,start+part.length(),android.text.Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);}start+=part.length()+11;}return text;}
 static String get(String address)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(address).openConnection();c.setConnectTimeout(7000);c.setReadTimeout(7000);c.setRequestProperty("User-Agent","PiTV/1.0 (personal home display)");try{if(c.getResponseCode()!=200)throw new IOException("Feed unavailable");try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>2*1024*1024)throw new IOException("Feed too large");out.write(b,0,n);}return out.toString("UTF-8");}}finally{c.disconnect();}}
 void fetch(){if(!active||closed)return;final int ticket=++generation;worker.submit(()->{String result=null;try{result=weather?weatherText():newsText();}catch(Exception ignored){}final String text=result;handler.post(()->{if(!active||closed||ticket!=generation)return;if(text!=null&&!text.isEmpty()){prefs.edit().putString(key()+"Text",text).putLong(key()+"At",System.currentTimeMillis()).apply();showCache(false);}else showCache(true);handler.postDelayed(refresh,text==null?60000:interval());});});}
 String weatherText()throws Exception{String lat=prefs.getString("latitude",""),lon=prefs.getString("longitude","");if(lat.isEmpty()||lon.isEmpty())return "Set your city or ZIP code for weather";return formatWeather(new JSONObject(get("https://api.open-meteo.com/v1/forecast?latitude="+lat+"&longitude="+lon+"&current=temperature_2m,apparent_temperature,weather_code,wind_speed_10m&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max&temperature_unit=fahrenheit&wind_speed_unit=mph&timezone=auto&forecast_days=8")));}
 static String formatWeather(JSONObject data)throws Exception{JSONObject c=data.getJSONObject("current"),d=data.getJSONObject("daily");JSONArray dates=d.getJSONArray("time"),high=d.getJSONArray("temperature_2m_max"),low=d.getJSONArray("temperature_2m_min"),codes=d.getJSONArray("weather_code"),rain=d.getJSONArray("precipitation_probability_max");StringBuilder out=new StringBuilder("NOW  ").append(temperature(c.opt("temperature_2m"))).append("F · ").append(condition(c.optInt("weather_code",-1))).append(" · Feels ").append(temperature(c.opt("apparent_temperature"))).append(" · Wind ").append(number(c.opt("wind_speed_10m"))).append(" mph");if(dates.length()>0)out.append("     •     TODAY  H ").append(temperature(high.opt(0))).append(" / L ").append(temperature(low.opt(0))).append(" · Rain ").append(number(rain.opt(0))).append("%");java.text.SimpleDateFormat parse=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US),label=new java.text.SimpleDateFormat("EEE M/d",Locale.US);parse.setTimeZone(java.util.TimeZone.getTimeZone("UTC"));label.setTimeZone(java.util.TimeZone.getTimeZone("UTC"));for(int i=1;i<Math.min(8,dates.length());i++){String day=label.format(parse.parse(dates.getString(i))).toUpperCase(Locale.US);out.append("     •     ").append(day).append("  ").append(condition(codes.optInt(i,-1))).append(" · H ").append(temperature(high.opt(i))).append(" / L ").append(temperature(low.opt(i))).append(" · Rain ").append(number(rain.opt(i))).append("%");}return out.toString();}
 static String number(Object value){return value instanceof Number?String.valueOf(Math.round(((Number)value).doubleValue())):"—";}static String temperature(Object value){return number(value)+"°";}
 static String condition(int code){if(code==0)return "Clear";if(code==1)return "Mostly clear";if(code==2)return "Partly cloudy";if(code==3)return "Overcast";if(code==45||code==48)return "Fog";if(code>=51&&code<=57)return "Drizzle";if(code>=61&&code<=67)return "Rain";if(code>=71&&code<=77)return "Snow";if(code>=80&&code<=82)return "Rain showers";if(code==85||code==86)return "Snow showers";if(code>=95&&code<=99)return "Thunderstorms";return "Conditions unavailable";}
 String newsText()throws Exception{XmlPullParser p=XmlPullParserFactory.newInstance().newPullParser();p.setInput(new StringReader(get("https://feeds.bbci.co.uk/news/world/rss.xml")));boolean item=false;ArrayList<String> titles=new ArrayList<>();for(int event=p.getEventType();event!=XmlPullParser.END_DOCUMENT&&titles.size()<10;event=p.next()){if(event==XmlPullParser.START_TAG&&"item".equals(p.getName()))item=true;else if(event==XmlPullParser.END_TAG&&"item".equals(p.getName()))item=false;else if(event==XmlPullParser.START_TAG&&item&&"title".equals(p.getName())){String title=p.nextText().replaceAll("\\s+"," ").trim();if(!title.isEmpty()&&!titles.contains(title))titles.add(title);}}if(titles.isEmpty())throw new IOException();StringBuilder tape=new StringBuilder("WORLD HEADLINES  •  BBC WORLD NEWS");for(String title:titles)tape.append("     •     ").append(title);return tape.toString();}
 void location(){EditText input=new EditText(getContext());input.setSingleLine(true);input.setText(prefs.getString("search",""));input.setHint("City or ZIP code");new AlertDialog.Builder(getContext()).setTitle("Weather location").setMessage("Enter a city or ZIP code, then choose the matching location. Location is saved on this Pi.").setView(input).setPositiveButton("Search",(d,w)->search(input.getText().toString().trim())).setNegativeButton("Cancel",null).show();}
 static JSONArray lookup(String query)throws Exception{if(query.matches("\\d{5}")){JSONObject zip=new JSONObject(get("https://api.zippopotam.us/us/"+query));JSONArray places=zip.getJSONArray("places"),result=new JSONArray();for(int i=0;i<places.length();i++){JSONObject p=places.getJSONObject(i);result.put(new JSONObject().put("name",p.getString("place name")+" "+query).put("admin1",p.getString("state abbreviation")).put("country","US").put("latitude",p.getString("latitude")).put("longitude",p.getString("longitude")));}return result;}return new JSONObject(get("https://geocoding-api.open-meteo.com/v1/search?name="+URLEncoder.encode(query,"UTF-8")+"&count=8&language=en&format=json")).optJSONArray("results");}
 void search(String query){if(query.isEmpty()||closed)return;Toast.makeText(getContext(),"Finding location…",0).show();worker.submit(()->{try{JSONArray results=lookup(query);if(results==null||results.length()==0)throw new IOException();String[] names=new String[results.length()];for(int i=0;i<names.length;i++){JSONObject r=results.getJSONObject(i);names[i]=r.getString("name")+", "+r.optString("admin1",r.optString("country"))+", "+r.optString("country","");}handler.post(()->{if(!active||closed)return;new AlertDialog.Builder(getContext()).setTitle("Choose weather location").setItems(names,(d,index)->{try{JSONObject r=results.getJSONObject(index);prefs.edit().putString("search",query).putString("place",names[index]).putString("latitude",r.getString("latitude")).putString("longitude",r.getString("longitude")).remove("weatherV2Text").remove("weatherV2At").apply();setText("Loading weather…");handler.removeCallbacks(refresh);fetch();}catch(JSONException ignored){}}).setNegativeButton("Cancel",null).show();});}catch(Exception e){handler.post(()->{if(active&&!closed)Toast.makeText(getContext(),"Location not found. Try the city name and country.",1).show();});}});}
}
